package vn.hust.restaurant.controller;import java.sql.*;import java.util.*;import vn.hust.restaurant.model.*;import vn.hust.restaurant.service.PaymentService;public class PaymentController{private final PaymentService s;public PaymentController(PaymentService s){this.s=s;}public List<Promotion>promotions()throws SQLException{return s.promotions();}public InvoicePreview preview(OrderSummary o,Integer c,Promotion p,int pts)throws SQLException{return s.preview(o,c,p,pts);}public long pay(InvoicePreview p,int e,List<PaymentPart>x)throws SQLException{return s.pay(p,e,x);}public Map<String,Object>invoice(long id)throws SQLException{return s.invoice(id);}}